import { Text } from "../i18n/LocalizedText";
import { Ionicons } from "@expo/vector-icons";import { router, useLocalSearchParams } from "expo-router";
import { useCallback, useEffect, useMemo, useState } from "react";
import { ActivityIndicator, Alert, Image, Modal, Platform, Pressable, ScrollView, StyleSheet, TextInput, useWindowDimensions, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { API_URL, useAuth } from "../auth/AuthContext";
import { colors } from "../theme";

type Variant = { id: string; variantValuesJson: string; sku: string; barcode: string; imageUrl: string | null; note: string | null; priceOverride: number | null; isDefault: boolean; avgLandedCost?: number; stock?: number; rowVer?: number[] };
type ProductImage = { id: string; imageUrl: string; sortOrder: number };
type MarketplaceSection = "STYLE" | "FEATURES_SPECS" | "ITEM_DETAILS";
type MarketplaceDetail = { id: string; section: MarketplaceSection; label: string; value: string; sortOrder: number };
type MarketplaceTemplate = { section: MarketplaceSection; label: string; valuePlaceholder: string | null; sortOrder: number };
type Product = { id: string; categoryId: string; name: string; sku: string; imageUrl: string | null; description: string | null; defectNotes: string | null; unitCode: string; sellingPrice: number; marketPrice: number | null; marketplacePrice: number | null; packagingCostPerUnit?: number; lowStockThreshold: number; attributesJson: string | null; note: string | null; status: string; categoryName: string; variants: Variant[]; rowVer?: number[]; showOnMarketplace?: boolean; youtubeUrl: string | null; marketplaceDetails: MarketplaceDetail[]; images: ProductImage[]; warrantyDurationValue: number | null; warrantyDurationUnit: string | null; wholesaleMinQty: number | null; wholesaleUnitPrice: number | null; wholesaleNote: string | null };
type Adjustment = { id: string; reason: string; qty: number; note: string | null; userName: string; createdAt: string };
type PriceSlot = { id: string; label: string; price: number; reason: string | null; isActive: boolean; createdAt: string; createdByName: string; startDate: string; endDate: string | null };
type CategoryField = { id: string; name: string; fieldType: string; optionsJson?: string | null; isVariant: boolean };
type Tab = "info" | "variants" | "prices" | "stock" | "marketplace";
const MEDIA_URL = "https://fileserverapi.lavlokshan.com";
const media = (value?: string | null) => !value ? null : /^https?:\/\//i.test(value) ? value : `${MEDIA_URL}${value}`;
const money = (value?: number | null) => `৳${Number(value ?? 0).toLocaleString("en-BD", { maximumFractionDigits: 2 })}`;
const variantName = (variant: Variant) => { try { const values = Object.values(JSON.parse(variant.variantValuesJson || "{}") as Record<string, string>).filter(Boolean); return values.length ? values.join(" / ") : variant.sku; } catch { return variant.sku; } };

export default function ProductDetailScreen() {
  const auth = useAuth(); const { id } = useLocalSearchParams<{ id: string }>();
  const role = auth.session?.user.role ?? "STAFF"; const isOwner = role === "OWNER"; const canAdjust = role === "OWNER" || role === "MANAGER";
  const [product, setProduct] = useState<Product | null>(null); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [tab, setTab] = useState<Tab>("info"); const [edit, setEdit] = useState(false); const [saving, setSaving] = useState(false); const [selectedVariantId, setSelectedVariantId] = useState<string | null>(null);
  const load = useCallback(async () => { if (!id) return; setLoading(true); setError(""); try { setProduct(await auth.api<Product>(`/products/${id}`)); } catch (e) { setError((e as Error).message); } finally { setLoading(false); } }, [id, auth.session?.businessId, auth.session?.branchId]);
  useEffect(() => { void load(); }, [load]);
  const archive = () => Alert.alert("Delete product", "This removes the product from active lists while preserving its order and purchase history.", [{ text: "Cancel", style: "cancel" }, { text: "Delete", style: "destructive", onPress: async () => { try { await auth.api(`/products/${id}/archive`, { method: "PATCH" }); router.replace("/products"); } catch (e) { setError((e as Error).message); } } }]);
  const totalStock = useMemo(() => product?.variants.reduce((sum, variant) => sum + Number(variant.stock ?? 0), 0) ?? 0, [product]);
  const tabs: { key: Tab; label: string }[] = [{ key: "info", label: "Info" }, { key: "variants", label: "Variants" }, ...(isOwner ? [{ key: "prices" as Tab, label: "Price Settings" }] : []), ...(canAdjust ? [{ key: "stock" as Tab, label: "Adjust Stock" }] : []), ...(isOwner ? [{ key: "marketplace" as Tab, label: "Marketplace" }] : [])];
  if (loading && !product) return <View style={s.state}><ActivityIndicator color={colors.primary} size="large" /><Text style={s.muted}>Loading product…</Text></View>;
  if (!product) return <View style={s.state}><Ionicons name="warning-outline" size={38} color={colors.danger} /><Text style={s.error}>{error || "Product not found."}</Text><Pressable onPress={() => void load()} style={s.primary}><Text style={s.primaryText}>Try again</Text></Pressable></View>;
  return <View style={s.root}>
    <View style={s.header}><View style={s.titleRow}><Pressable onPress={() => router.replace("/products")} hitSlop={8}><Ionicons name="chevron-back" size={23} color={colors.secondary} /></Pressable><View style={s.titleCopy}><Text numberOfLines={1} style={s.title}>{product.name}</Text><Text style={s.subtitle}>{product.sku} · {product.categoryName}</Text></View>{isOwner && product.status === "ACTIVE" && <Pressable onPress={archive} style={s.deleteButton}><Text style={s.deleteText}>Delete</Text></Pressable>}</View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.tabs}>{tabs.map(item => <Pressable key={item.key} onPress={() => setTab(item.key)} style={[s.tab, tab === item.key && s.activeTab]}><Text style={[s.tabText, tab === item.key && s.activeTabText]}>{item.label}</Text></Pressable>)}</ScrollView></View>
    <ScrollView contentContainerStyle={s.content}>{!!error && <Text style={s.errorBox}>{error}</Text>}{tab === "info" && <Info product={product} totalStock={totalStock} owner={isOwner} edit={() => setEdit(true)} go={setTab} />}{tab === "variants" && <Variants product={product} auth={auth} owner={isOwner} canAdjust={canAdjust} reload={load} price={variant => { setSelectedVariantId(variant.id); setTab("prices"); }} stock={variant => { setSelectedVariantId(variant.id); setTab("stock"); }} />}{tab === "prices" && isOwner && <Prices product={product} auth={auth} reload={load} initialVariantId={selectedVariantId} />}{tab === "stock" && canAdjust && <Stock product={product} auth={auth} reload={load} initialVariantId={selectedVariantId} />}{tab === "marketplace" && isOwner && <Marketplace product={product} auth={auth} reload={load} />}</ScrollView>
    <EditModal visible={edit} product={product} saving={saving} close={() => setEdit(false)} save={async payload => { setSaving(true); setError(""); try { const updated = await auth.api<Product>(`/products/${id}`, { method: "PUT", body: JSON.stringify(payload) }); setProduct(updated); setEdit(false); } catch (e) { setError((e as Error).message); } finally { setSaving(false); } }} />
  </View>;
}

function Info({ product, totalStock, owner, edit, go }: { product: Product; totalStock: number; owner: boolean; edit: () => void; go: (tab: Tab) => void }) {
  const source = media(product.imageUrl); const out = totalStock <= 0; const low = !out && totalStock <= product.lowStockThreshold; const warranty = product.warrantyDurationValue ? `${product.warrantyDurationValue} ${product.warrantyDurationUnit ?? ""}` : "No warranty";
  return <View style={s.sections}>{source ? <View style={s.hero}><Image source={{ uri: source }} resizeMode="contain" style={s.heroImage} /></View> : <View style={s.hero}><Ionicons name="cube-outline" size={70} color={colors.muted} /></View>}{product.images?.length > 0 && <View style={s.gallery}>{product.images.map(image => <Image key={image.id} source={{ uri: media(image.imageUrl)! }} resizeMode="contain" style={s.galleryImage} />)}</View>}
    <View style={s.card}><View style={s.cardHead}><Text style={s.cardLabel}>Product details</Text>{owner && <Pressable onPress={edit} style={s.roundAction}><Ionicons name="create-outline" size={21} color={colors.primaryDark} /></Pressable>}</View><Text style={s.detailLabel}>Product Name</Text><Text style={s.detailValue}>{product.name}</Text>{!!product.description && <><Text style={s.detailLabel}>Description</Text><Text style={s.detailValue}>{product.description}</Text></>}<View style={s.warranty}><Text style={s.warrantyText}>Warranty: {warranty}</Text></View></View>
    <View style={[s.stockCard, out ? s.stockOut : low ? s.stockLow : s.stockGood]}><Text style={s.stockCaption}>Stock</Text><View style={s.stockRow}><Text style={s.stockValue}>{totalStock} <Text style={s.stockUnit}>{product.unitCode}</Text></Text><Text style={[s.stockBadge, out ? s.badgeDanger : low ? s.badgeWarning : s.badgeSuccess]}>{out ? "Out of Stock" : low ? "Low Stock" : "In Stock"}</Text>{owner && <Pressable onPress={() => go("stock")} style={s.lightButton}><Text style={s.lightButtonText}>Restock Now</Text></Pressable>}</View><Text style={s.smallMuted}>Low Stock Alert: {product.lowStockThreshold} {product.unitCode}</Text></View>
    <View style={s.variantCard}><View style={s.cardHead}><Text style={s.variantHeading}>Variants</Text><Pressable onPress={() => go("variants")}><Text style={s.variantAction}>View all</Text></Pressable></View>{product.variants.map(variant => <VariantRow key={variant.id} variant={variant} product={product} />)}</View>
    <View style={s.priceCard}><Ionicons name="pricetag-outline" size={23} color={colors.primaryDark} /><View style={s.grow}><Text style={s.priceTitle}>Selling price</Text><Text style={s.priceValue}>{money(product.sellingPrice)}</Text></View>{product.marketPrice && product.marketPrice > product.sellingPrice && <Text style={s.oldPrice}>{money(product.marketPrice)}</Text>}{owner && <Pressable onPress={() => go("prices")}><Text style={s.actionText}>Adjust price</Text></Pressable>}</View>
  </View>;
}
function VariantRow({ variant, product }: { variant: Variant; product: Product }) { const source = media(variant.imageUrl || product.imageUrl); const price = variant.priceOverride ?? product.sellingPrice; return <View style={s.variantRow}>{source ? <Image source={{ uri: source }} style={s.variantImage} /> : <View style={s.variantImage}><Ionicons name="cube-outline" size={18} color={colors.muted} /></View>}<View style={s.grow}><Text numberOfLines={1} style={s.variantName}>{variantName(variant)}</Text><Text style={s.variantSku}>{variant.sku}</Text></View><View style={s.right}><Text style={s.variantPrice}>{money(price)}</Text><Text style={s.variantStock}>{variant.stock ?? 0} in stock</Text></View></View>; }
function Variants({ product, auth, owner, canAdjust, reload, price, stock }: { product: Product; auth: ReturnType<typeof useAuth>; owner: boolean; canAdjust: boolean; reload: () => Promise<void>; price: (variant: Variant) => void; stock: (variant: Variant) => void }) {
  const [labelQty, setLabelQty] = useState("1"); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [showAdd, setShowAdd] = useState(false); const [showSplit, setShowSplit] = useState(false); const [categoryFields, setCategoryFields] = useState<CategoryField[]>([]);
  const [name, setName] = useState(""); const [values, setValues] = useState<Record<string, string>>({}); const [imageUrl, setImageUrl] = useState<string | null>(null); const [note, setNote] = useState(""); const [override, setOverride] = useState(""); const [qty, setQty] = useState(""); const [cost, setCost] = useState("");
  const [splitRows, setSplitRows] = useState([{ name: "", qty: "" }, { name: "", qty: "" }]);
  const images = Array.from(new Set([product.imageUrl, ...(product.images ?? []).map(item => item.imageUrl)].filter(Boolean))) as string[];
  const source = product.variants.length === 1 ? product.variants[0] : null; const sourceStock = Number(source?.stock ?? 0); const needsSplit = !!source && sourceStock > 0; const splitTotal = splitRows.reduce((sum, row) => sum + (Number(row.qty) || 0), 0); const splitMatches = Math.abs(splitTotal - sourceStock) < .0005;
  useEffect(() => { if (owner) auth.api<{ fields: CategoryField[] }>(`/categories/${product.categoryId}`).then(value => setCategoryFields(value.fields.filter(field => field.isVariant))).catch(() => setCategoryFields([])); }, [product.categoryId, owner]);
  const run = async (action: () => Promise<void>) => { setBusy(true); setError(""); try { await action(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  const chooseImage = (variant: Variant, next: string | null) => run(async () => { await auth.api(`/products/${product.id}/variants/${variant.id}`, { method: "PUT", body: JSON.stringify({ imageUrl: next, note: variant.note, priceOverride: variant.priceOverride, isDefault: variant.isDefault, rowVer: variant.rowVer }) }); await reload(); });
  const add = () => run(async () => { if (Number(qty) <= 0) throw new Error("Initial stock must be greater than zero."); if (cost === "" || Number(cost) < 0) throw new Error("Enter a valid buy price."); await auth.api(`/products/${product.id}/variants`, { method: "POST", body: JSON.stringify({ variantValuesJson: JSON.stringify(name.trim() ? { Name: name.trim(), ...values } : values), barcode: null, imageUrl, note: note.trim() || null, priceOverride: override ? Number(override) : null, isDefault: false, qty: Number(qty), costPrice: Number(cost), branchId: auth.session?.branchId }) }); setShowAdd(false); setName(""); setValues({}); setImageUrl(null); setNote(""); setOverride(""); setQty(""); setCost(""); await reload(); });
  const split = () => run(async () => { if (!splitRows.every(row => row.name.trim() && Number(row.qty) > 0)) throw new Error("Enter a name and quantity for every variant."); if (!splitMatches) throw new Error(`Variant quantities must total ${sourceStock}.`); await auth.api(`/products/${product.id}/variants/split`, { method: "POST", body: JSON.stringify({ sourceVariantId: source!.id, items: splitRows.map(row => ({ values: { Name: row.name.trim() }, qty: Number(row.qty) })), branchId: auth.session?.branchId }) }); setShowSplit(false); await reload(); });
  const printLabels = async (variantId?: string) => { if (Platform.OS !== "web" || typeof window === "undefined") { Alert.alert("Barcode labels", "Barcode PDF download is currently available from the web version."); return; } setBusy(true); setError(""); try { const query = new URLSearchParams({ qty: String(Math.max(1, Number(labelQty) || 1)) }); if (variantId) query.set("variantId", variantId); const response = await fetch(`${API_URL}/products/${product.id}/barcode-labels?${query}`, { headers: { Authorization: `Bearer ${auth.session?.accessToken}`, ...(auth.session?.businessId ? { "X-Business-Id": auth.session.businessId } : {}), ...(auth.session?.branchId ? { "X-Branch-Id": auth.session.branchId } : {}) } }); if (!response.ok) throw new Error("Could not generate barcode labels."); const url = URL.createObjectURL(await response.blob()); window.open(url, "_blank"); setTimeout(() => URL.revokeObjectURL(url), 60000); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <View style={s.sections}>
    {owner && <View style={s.labelToolbar}><Text style={s.smallMuted}>Qty per label</Text><TextInput value={labelQty} onChangeText={setLabelQty} keyboardType="number-pad" style={s.qtyInput} /><Pressable disabled={busy} onPress={() => void printLabels()} style={s.outlineButton}><Text style={s.actionText}>🖨 Print All Labels</Text></Pressable></View>}
    {!!error && <Text style={s.errorBox}>{error}</Text>}
    {product.variants.map(variant => { const currentImage = media(variant.imageUrl || product.imageUrl); return <View key={variant.id} style={s.variantDetailCard}>
      {owner && <><View style={s.variantHero}>{currentImage ? <Image source={{ uri: currentImage }} resizeMode="contain" style={s.heroImage} /> : <Ionicons name="image-outline" size={45} color={colors.muted} />}</View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.imageChoices}><Pressable onPress={() => void chooseImage(variant, null)} style={s.removeImage}><Ionicons name="trash-outline" size={18} color={colors.danger} /><Text style={s.deleteText}>Use product photo</Text></Pressable>{images.map(value => <Pressable key={value} onPress={() => void chooseImage(variant, value)} style={[s.imageChoice, variant.imageUrl === value && s.imageChoiceActive]}><Image source={{ uri: media(value)! }} resizeMode="contain" style={s.choiceImage} /></Pressable>)}</ScrollView><Text style={s.smallMuted}>Optional — falls back to the product photo if not set</Text></>}
      <View style={s.variantMeta}><View style={s.grow}><Text style={s.variantName}>{variantName(variant)}</Text><Text style={s.smallMuted}>SKU: {variant.sku}</Text><Text style={s.smallMuted}>Barcode: {variant.barcode}</Text>{variant.note && <Text style={s.note}>{variant.note}</Text>}</View><View style={s.right}>{variant.priceOverride != null ? <Text style={s.priceAccent}>{money(variant.priceOverride)}</Text> : <Text style={s.smallMuted}>(base price)</Text>}{owner && Number(variant.avgLandedCost ?? 0) > 0 && <Text style={s.smallMuted}>Cost: {money(variant.avgLandedCost)}</Text>}<Text style={s.smallMuted}>Stock: {variant.stock ?? 0}</Text></View></View>
      {(owner || canAdjust) && <View style={s.variantActions}>{owner && <Pressable onPress={() => price(variant)} style={s.offerButton}><Text style={s.actionText}>Offers →</Text></Pressable>}{canAdjust && <Pressable onPress={() => stock(variant)} style={s.stockButton}><Text style={s.stockButtonText}>Adjust Stock →</Text></Pressable>}{owner && <Pressable disabled={busy} onPress={() => void printLabels(variant.id)} style={s.labelButton}><Text style={s.smallMuted}>🖨 Label</Text></Pressable>}</View>}
    </View>; })}
    {owner && !showAdd && !showSplit && <Pressable onPress={() => needsSplit ? setShowSplit(true) : setShowAdd(true)} style={s.dashedButton}><Text style={s.actionText}>{needsSplit ? "Split into Variants" : "Add Variant"}</Text></Pressable>}
    {owner && showSplit && source && <View style={s.variantForm}><Text style={s.sectionTitle}>Split Existing Stock into Variants</Text><Text style={s.muted}>Allocate all {sourceStock} existing units between the new variants.</Text>{splitRows.map((row, index) => <View key={index} style={s.splitRow}><TextInput value={row.name} onChangeText={value => setSplitRows(current => current.map((item, i) => i === index ? { ...item, name: value } : item))} placeholder={`Variant ${index + 1} name`} placeholderTextColor={colors.muted} style={[s.input, s.grow]} /><TextInput value={row.qty} onChangeText={value => setSplitRows(current => current.map((item, i) => i === index ? { ...item, qty: value } : item))} placeholder="Qty" placeholderTextColor={colors.muted} keyboardType="decimal-pad" style={s.splitQty} />{splitRows.length > 2 && <Pressable onPress={() => setSplitRows(current => current.filter((_, i) => i !== index))}><Ionicons name="close-circle" size={22} color={colors.danger} /></Pressable>}</View>)}<Pressable onPress={() => setSplitRows(current => [...current, { name: "", qty: "" }])} style={s.dashedSmall}><Text style={s.actionText}>Add another variant</Text></Pressable><Text style={[s.splitTotal, splitMatches ? s.positive : s.negative]}>Total: {splitTotal} / {sourceStock}</Text><View style={s.formActions}><Pressable onPress={() => setShowSplit(false)} style={s.cancelButton}><Text style={s.muted}>Cancel</Text></Pressable><Pressable disabled={busy || !splitMatches} onPress={() => void split()} style={[s.primary, s.grow, (busy || !splitMatches) && s.disabled]}><Text style={s.primaryText}>Save Variants</Text></Pressable></View></View>}
    {owner && showAdd && <View style={s.variantForm}><Text style={s.sectionTitle}>Add New Variant</Text><TextInput value={name} onChangeText={setName} placeholder="Variant Name (optional)" placeholderTextColor={colors.muted} style={s.input} />{categoryFields.map(field => <TextInput key={field.id} value={values[field.name] ?? ""} onChangeText={value => setValues(current => ({ ...current, [field.name]: value }))} placeholder={field.name} placeholderTextColor={colors.muted} style={s.input} />)}<TextInput value={override} onChangeText={setOverride} placeholder="Price override (optional)" placeholderTextColor={colors.muted} keyboardType="decimal-pad" style={s.input} /><View style={s.splitRow}><TextInput value={qty} onChangeText={setQty} placeholder="Initial stock" placeholderTextColor={colors.muted} keyboardType="decimal-pad" style={[s.input, s.grow]} /><TextInput value={cost} onChangeText={setCost} placeholder="Buy price" placeholderTextColor={colors.muted} keyboardType="decimal-pad" style={[s.input, s.grow]} /></View><TextInput value={note} onChangeText={setNote} placeholder="Details (optional)" placeholderTextColor={colors.muted} multiline style={[s.input, s.textarea]} />{!!images.length && <><Text style={s.smallMuted}>Choose existing image (optional)</Text><ScrollView horizontal contentContainerStyle={s.imageChoices}>{images.map(value => <Pressable key={value} onPress={() => setImageUrl(value)} style={[s.imageChoice, imageUrl === value && s.imageChoiceActive]}><Image source={{ uri: media(value)! }} resizeMode="contain" style={s.choiceImage} /></Pressable>)}</ScrollView></>}<View style={s.formActions}><Pressable onPress={() => setShowAdd(false)} style={s.cancelButton}><Text style={s.muted}>Cancel</Text></Pressable><Pressable disabled={busy} onPress={() => void add()} style={[s.primary, s.grow, busy && s.disabled]}><Text style={s.primaryText}>Add Variant</Text></Pressable></View></View>}
  </View>;
}
function Prices({ product, auth, reload, initialVariantId }: { product: Product; auth: ReturnType<typeof useAuth>; reload: () => Promise<void>; initialVariantId?: string | null }) {
  const [selected, setSelected] = useState<Set<string>>(() => new Set(initialVariantId ? [initialVariantId] : product.variants.map(item => item.id)));
  const active = product.variants.find(item => selected.has(item.id)) ?? product.variants[0];
  const [slots, setSlots] = useState<PriceSlot[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [offerOpen, setOfferOpen] = useState(false); const [sellOpen, setSellOpen] = useState(false); const [costOpen, setCostOpen] = useState(false);
  const [offerPct, setOfferPct] = useState("10"); const [reason, setReason] = useState(""); const [startDate, setStartDate] = useState(""); const [duration, setDuration] = useState<"none" | "7" | "30" | "custom">("none"); const [endDate, setEndDate] = useState(""); const [sellPrice, setSellPrice] = useState(""); const [costPerUnit, setCostPerUnit] = useState("");
  const offerSlots = slots.filter(slot => slot.label !== "Original Price"); const activeSlot = slots.find(slot => slot.isActive); const referencePrice = product.marketPrice ?? product.sellingPrice; const effectivePrice = activeSlot?.price ?? active?.priceOverride ?? product.sellingPrice; const totalCost = Number(active?.avgLandedCost ?? 0) + Number(product.packagingCostPerUnit ?? 0); const profit = effectivePrice - totalCost; const costNotSet = Number(active?.stock ?? 0) > 0 && Number(active?.avgLandedCost ?? 0) === 0;
  const loadSlots = useCallback(async () => { if (!active) return; try { setSlots(await auth.api<PriceSlot[]>(`/products/variants/${active.id}/slots`)); } catch (e) { setError((e as Error).message); } }, [active?.id]);
  useEffect(() => { void loadSlots(); }, [loadSlots]);
  const run = async (action: () => Promise<void>) => { setBusy(true); setError(""); try { await action(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  const activate = (slot: PriceSlot) => run(async () => { await auth.api(`/products/variants/${active.id}/slots/${slot.id}/activate`, { method: "POST" }); await Promise.all([loadSlots(), reload()]); });
  const deleteOffer = (slot: PriceSlot) => Alert.alert("Delete offer", "This permanently removes the offer.", [{ text: "Cancel", style: "cancel" }, { text: "Delete", style: "destructive", onPress: () => void run(async () => { await auth.api(`/products/variants/${active.id}/slots/${slot.id}`, { method: "DELETE" }); await loadSlots(); }) }]);
  const unapply = () => Alert.alert("Remove current offer?", "The price will go back to the regular sell price.", [{ text: "Cancel", style: "cancel" }, { text: "Unapply", style: "destructive", onPress: () => void run(async () => { const slot = await auth.api<PriceSlot>(`/products/variants/${active.id}/slots`, { method: "POST", body: JSON.stringify({ label: "Original Price", newPrice: referencePrice, reason: null }) }); await auth.api(`/products/variants/${active.id}/slots/${slot.id}/activate`, { method: "POST" }); await Promise.all([loadSlots(), reload()]); }) }]);
  const openOffer = () => { setOfferPct("10"); setReason(""); setStartDate(new Date().toISOString().slice(0, 16)); setDuration("none"); setEndDate(""); setOfferOpen(true); };
  const createOffer = () => run(async () => { const pct = Math.min(90, Math.max(0, Number(offerPct))); if (!Number.isFinite(pct)) throw new Error("Enter a valid discount percentage."); if (!startDate) throw new Error("Start date is required."); if (!selected.size) throw new Error("Select at least one variant."); if (duration === "custom" && !endDate) throw new Error("End date is required."); const start = new Date(startDate); if (Number.isNaN(start.getTime())) throw new Error("Enter a valid start date."); const finish = duration === "none" ? null : duration === "custom" ? new Date(endDate) : new Date(start.getTime() + Number(duration) * 86400000); if (finish && (Number.isNaN(finish.getTime()) || finish <= start)) throw new Error("End date must be after the start date."); const label = `Offer ${Math.round(pct)}%`; for (const variant of product.variants.filter(item => selected.has(item.id))) { const base = variant.priceOverride ?? referencePrice; const price = Math.round(base * (1 - pct / 100) * 100) / 100; const slot = await auth.api<PriceSlot>(`/products/variants/${variant.id}/slots`, { method: "POST", body: JSON.stringify({ label, newPrice: price, reason: reason.trim() || null, startDate: start.toISOString(), endDate: finish?.toISOString() ?? null }) }); if (start <= new Date()) await auth.api(`/products/variants/${variant.id}/slots/${slot.id}/activate`, { method: "POST" }); } setOfferOpen(false); await Promise.all([loadSlots(), reload()]); });
  const productUpdatePayload = (marketPrice: number) => ({ categoryId: product.categoryId, name: product.name, imageUrl: product.imageUrl, description: product.description, defectNotes: product.defectNotes, unitCode: product.unitCode, sellingPrice: product.sellingPrice, marketPrice, packagingCostPerUnit: product.packagingCostPerUnit ?? 0, lowStockThreshold: product.lowStockThreshold, attributesJson: product.attributesJson, note: product.note, status: product.status, rowVer: product.rowVer, warrantyDurationValue: product.warrantyDurationValue, warrantyDurationUnit: product.warrantyDurationUnit, wholesaleMinQty: product.wholesaleMinQty, wholesaleUnitPrice: product.wholesaleUnitPrice, wholesaleNote: product.wholesaleNote });
  const updateSellPrice = () => run(async () => { const value = Number(sellPrice); if (!Number.isFinite(value) || value <= 0) throw new Error("Selling price must be greater than zero."); await auth.api(`/products/${product.id}`, { method: "PUT", body: JSON.stringify(productUpdatePayload(value)) }); const currentOffer = offerSlots.find(slot => slot.isActive); const match = currentOffer?.label.match(/(\d+(?:\.\d+)?)%/); if (currentOffer && match) { const pct = Number(match[1]); const replacement = await auth.api<PriceSlot>(`/products/variants/${active.id}/slots`, { method: "POST", body: JSON.stringify({ label: currentOffer.label, newPrice: value * (1 - pct / 100), reason: currentOffer.reason }) }); await auth.api(`/products/variants/${active.id}/slots/${replacement.id}/activate`, { method: "POST" }); } setSellOpen(false); await Promise.all([loadSlots(), reload()]); });
  const recordCost = () => run(async () => { const value = Number(costPerUnit); if (!Number.isFinite(value) || value < 0) throw new Error("Enter a valid purchase cost."); await auth.api(`/products/variants/${active.id}/existing-stock-cost`, { method: "POST", body: JSON.stringify({ qty: active.stock ?? 0, costPerUnit: value, branchId: auth.session?.branchId }) }); setCostOpen(false); setCostPerUnit(""); await reload(); });
  const toggle = (id: string) => setSelected(current => { const next = new Set(current); next.has(id) ? next.delete(id) : next.add(id); return next; });
  if (!active) return <Text style={s.empty}>No variants available.</Text>;
  return <View style={s.sections}>
    {product.variants.length > 1 && <View><Text style={s.detailLabel}>SELECT VARIANT</Text><View style={s.priceVariantChips}><Pressable onPress={() => setSelected(selected.size === product.variants.length ? new Set() : new Set(product.variants.map(item => item.id)))} style={[s.priceVariantChip, selected.size === product.variants.length && s.priceVariantChipActive]}><Text style={[s.chipText, selected.size === product.variants.length && s.activeChipText]}>All variants</Text></Pressable>{product.variants.map(variant => <Pressable key={variant.id} onPress={() => toggle(variant.id)} style={[s.priceVariantChip, selected.has(variant.id) && s.priceVariantChipActive]}><Text style={[s.chipText, selected.has(variant.id) && s.activeChipText]}>{variantName(variant)}</Text></Pressable>)}</View></View>}
    {!!error && <Text style={s.errorBox}>{error}</Text>}
    {costNotSet && !costOpen && <Pressable onPress={() => setCostOpen(true)} style={s.costWarning}><Text style={s.costWarningTitle}>Purchase price is not set</Text><Text style={s.costWarningText}>Add Price for Previous {active.stock ?? 0} Stock</Text></Pressable>}
    {costNotSet && costOpen && <View style={s.costForm}><Text style={s.sectionTitle}>Add Price for Previous {active.stock ?? 0} Stock</Text><Text style={s.muted}>Enter what you paid per unit. This can only be used once for existing stock.</Text><TextInput value={costPerUnit} onChangeText={setCostPerUnit} keyboardType="decimal-pad" placeholder="Cost per unit" placeholderTextColor={colors.muted} style={s.input} /><View style={s.formActions}><Pressable onPress={() => setCostOpen(false)} style={s.cancelButton}><Text style={s.muted}>Cancel</Text></Pressable><Pressable disabled={busy} onPress={() => void recordCost()} style={[s.primary, s.grow, busy && s.disabled]}><Text style={s.primaryText}>Save</Text></Pressable></View></View>}
    <View style={s.sellCard}><View style={s.cardHead}><Text style={s.sellCaption}>Current Selling Price</Text><Pressable onPress={() => { setSellPrice(String(referencePrice)); setSellOpen(true); }}><Ionicons name="create-outline" size={19} color={colors.white} /></Pressable></View><View style={s.sellPriceRow}><Text style={s.sellPrice}>{money(effectivePrice)}</Text>{referencePrice > effectivePrice && <Text style={s.sellOldPrice}>{money(referencePrice)}</Text>}{activeSlot && offerSlots.some(slot => slot.isActive) && <Text style={s.offerBadge}>{activeSlot.label}</Text>}</View>{!costNotSet && <View style={s.costRows}><PriceLine label="Product Purchase Cost" value={money(totalCost)} /><PriceLine label="Profit" value={money(profit)} positive={profit >= 0} /></View>}</View>
    {!!offerSlots.length && <View><Text style={s.detailLabel}>OFFERS</Text><View style={s.offerList}>{[...offerSlots].sort((a, b) => Number(b.isActive) - Number(a.isActive)).map(slot => <View key={slot.id} style={[s.offerRow, slot.isActive && s.offerActive]}><View style={[s.radio, slot.isActive && s.radioActive]}>{slot.isActive && <View style={s.radioDot} />}</View><View style={s.grow}><View style={s.offerTitleRow}><Text style={[s.offerTitle, slot.isActive && s.offerActiveTitle]}>{slot.label}</Text>{slot.isActive && <Text style={s.currentBadge}>Currently Used</Text>}</View><Text style={s.smallMuted}>New price: {money(slot.price)}</Text>{slot.reason && <Text style={s.smallMuted}>{slot.reason}</Text>}<Text style={s.smallMuted}>Created by {slot.createdByName} · {new Date(slot.createdAt).toLocaleDateString()}</Text>{slot.endDate && slot.isActive && <Text style={s.expiry}>Active until {new Date(slot.endDate).toLocaleString()}</Text>}</View><View style={s.offerActions}>{slot.isActive ? <Pressable onPress={unapply} style={s.unapplyButton}><Text style={s.unapplyText}>Unapply</Text></Pressable> : <><Pressable onPress={() => void activate(slot)} style={s.applyButton}><Text style={s.applyText}>Apply</Text></Pressable><Pressable onPress={() => deleteOffer(slot)}><Text style={s.deleteText}>Delete</Text></Pressable></>}</View></View>)}</View></View>}
    {!costNotSet && <Pressable onPress={openOffer} style={s.primary}><Text style={s.primaryText}>Change Price / New Offer</Text></Pressable>}
    <PriceSheet visible={offerOpen} title="New Offer" close={() => setOfferOpen(false)}><View style={s.offerPreview}><PriceLine label="Purchase Price" value={money(totalCost)} /><PriceLine label="Selling Price" value={money(referencePrice)} /><PriceLine label="Discount" value={`${Math.min(90, Math.max(0, Number(offerPct) || 0))}%`} /><PriceLine label="Price After Discount" value={money(referencePrice * (1 - Math.min(90, Math.max(0, Number(offerPct) || 0)) / 100))} /></View><Label text="Discount percentage (0–90)" /><TextInput value={offerPct} onChangeText={setOfferPct} keyboardType="number-pad" style={s.input} /><Label text="Note (optional)" /><TextInput value={reason} onChangeText={setReason} style={s.input} /><Label text="Start date and time" /><TextInput value={startDate} onChangeText={setStartDate} placeholder="YYYY-MM-DDTHH:mm" placeholderTextColor={colors.muted} style={s.input} /><Label text="End date" /><View style={s.durationRow}>{(["none", "7", "30", "custom"] as const).map(value => <Pressable key={value} onPress={() => setDuration(value)} style={[s.durationButton, duration === value && s.durationActive]}><Text style={[s.durationText, duration === value && s.durationActiveText]}>{value === "none" ? "No end" : value === "custom" ? "Custom" : `${value} days`}</Text></Pressable>)}</View>{duration === "custom" && <TextInput value={endDate} onChangeText={setEndDate} placeholder="YYYY-MM-DDTHH:mm" placeholderTextColor={colors.muted} style={s.input} />}<Pressable disabled={busy} onPress={() => void createOffer()} style={[s.primary, busy && s.disabled]}><Text style={s.primaryText}>{busy ? "Creating…" : "Create Offer"}</Text></Pressable></PriceSheet>
    <PriceSheet visible={sellOpen} title="Edit Selling Price" close={() => setSellOpen(false)}><View style={s.offerPreview}><PriceLine label="Purchase Price" value={money(totalCost)} /><PriceLine label="Current Sell Price" value={money(referencePrice)} /><PriceLine label="Current Price After Discount" value={money(effectivePrice)} /></View><Label text="New selling price" /><TextInput value={sellPrice} onChangeText={setSellPrice} keyboardType="decimal-pad" style={s.input} /><Pressable disabled={busy} onPress={() => void updateSellPrice()} style={[s.primary, busy && s.disabled]}><Text style={s.primaryText}>Save Selling Price</Text></Pressable></PriceSheet>
  </View>;
}
function PriceLine({ label, value, positive }: { label: string; value: string; positive?: boolean }) { return <View style={s.priceLine}><Text style={s.priceLineLabel}>{label}</Text><Text style={[s.priceLineValue, positive !== undefined && (positive ? s.profitPositive : s.profitNegative)]}>{value}</Text></View>; }
function PriceSheet({ visible, title, close, children }: { visible: boolean; title: string; close: () => void; children: React.ReactNode }) { return <Modal visible={visible} transparent animationType="slide" onRequestClose={close}><View style={s.overlay}><SafeAreaView style={s.priceModal}><View style={s.modalHead}><Text style={s.modalTitle}>{title}</Text><Pressable onPress={close}><Ionicons name="close" size={24} color={colors.heading} /></Pressable></View><ScrollView contentContainerStyle={s.priceModalContent}>{children}</ScrollView></SafeAreaView></View></Modal>; }

function Stock({ product, auth, reload, initialVariantId }: { product: Product; auth: ReturnType<typeof useAuth>; reload: () => Promise<void>; initialVariantId?: string | null }) {
  type StockMode = "ADD" | "DEDUCT" | "RECOUNT"; type StockReason = "EXISTING_STOCK" | "FOUND_EXTRA" | "OTHER" | "DAMAGED" | "LOST_THEFT" | "RECOUNT";
  const reasons: Record<StockMode, StockReason[]> = { ADD: ["EXISTING_STOCK", "FOUND_EXTRA", "OTHER"], DEDUCT: ["DAMAGED", "LOST_THEFT", "OTHER"], RECOUNT: ["RECOUNT"] };
  const reasonLabel: Record<StockReason, string> = { EXISTING_STOCK: "Existing stock", FOUND_EXTRA: "Found extra", OTHER: "Other", DAMAGED: "Damaged", LOST_THEFT: "Lost / theft", RECOUNT: "Recount" };
  const { width } = useWindowDimensions(); const mobile = width < 768;
  const [variantId, setVariantId] = useState(initialVariantId ?? product.variants[0]?.id ?? ""); const [mode, setMode] = useState<StockMode | null>(null); const [reason, setReason] = useState<StockReason>("EXISTING_STOCK"); const [value, setValue] = useState("1"); const [note, setNote] = useState(""); const [history, setHistory] = useState<Adjustment[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const active = product.variants.find(item => item.id === variantId) ?? product.variants[0];
  useEffect(() => { if (active) auth.api<Adjustment[]>(`/products/variants/${active.id}/stock-adjustments`).then(setHistory).catch(() => setHistory([])); }, [active?.id]);
  const currentStock = Number(active?.stock ?? 0); const entered = Number(value) || 0; const projected = mode === "DEDUCT" ? Math.max(0, currentStock - entered) : mode === "RECOUNT" ? entered : currentStock + entered;
  const close = () => { setMode(null); setValue("1"); setNote(""); setError(""); };
  const open = (next: StockMode) => { setMode(next); setReason(reasons[next][0]); setValue(next === "RECOUNT" ? String(currentStock) : "1"); setNote(""); setError(""); };
  const step = (change: number) => { const minimum = mode === "RECOUNT" ? 0 : 1; setValue(String(Math.max(minimum, (Number(value) || 0) + change))); };
  const submit = async () => { if (!mode || !active) return; const qty = Number(value); const minimum = mode === "RECOUNT" ? 0 : 1; if (!value || !Number.isFinite(qty) || qty < minimum) { setError(mode === "RECOUNT" ? "Enter a stock quantity of zero or more." : "Quantity must be at least 1."); return; } setBusy(true); setError(""); try { await auth.api(`/products/variants/${active.id}/stock-adjustments`, { method: "POST", body: JSON.stringify({ reason: mode === "RECOUNT" ? "RECOUNT" : reason, mode: mode === "RECOUNT" ? "SET" : "DELTA", value: mode === "DEDUCT" ? -qty : qty, note: note.trim() || null }) }); await reload(); setHistory(await auth.api<Adjustment[]>(`/products/variants/${active.id}/stock-adjustments`)); close(); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  if (!active) return <Text style={s.muted}>No variants available.</Text>;
  return <View style={s.sections}><View style={s.stockOverview}>{product.variants.length > 1 && <><Text style={s.stockOverviewLabel}>SELECT VARIANT</Text><View style={s.priceVariantChips}>{product.variants.map(item => <Pressable key={item.id} onPress={() => setVariantId(item.id)} style={[s.priceVariantChip, active.id === item.id && s.priceVariantChipActive]}><Text style={[s.chipText, active.id === item.id && s.activeChipText]}>{variantName(item)}</Text></Pressable>)}</View></>}<View style={s.stockOverviewRow}><Text style={s.stockOverviewLabel}>CURRENT STOCK</Text><Text style={[s.currentStock, currentStock <= 0 && s.negative]}>{currentStock}</Text></View>{currentStock <= 0 && <Text style={s.outOfStock}>Out of stock — add more stock</Text>}</View><View style={s.stockActions}><Pressable onPress={() => open("ADD")} style={[s.stockAction, s.addAction]}><Text style={s.addActionText}>+ Add Stock</Text></Pressable><Pressable onPress={() => open("DEDUCT")} style={[s.stockAction, s.deductAction]}><Text style={s.deductActionText}>− Deduct Stock</Text></Pressable><Pressable onPress={() => open("RECOUNT")} style={[s.stockAction, s.recountAction]}><Text style={s.recountActionText}>Recount</Text></Pressable></View><View><Text style={s.historyTitle}>ADJUSTMENT HISTORY</Text>{history.length ? <View style={s.offerList}>{history.map(item => <View key={item.id} style={s.historyRow}><View style={s.grow}><Text style={s.variantName}>{reasonLabel[item.reason as StockReason] ?? "Other"}</Text>{item.note && <Text style={s.smallMuted}>{item.note}</Text>}<Text style={s.smallMuted}>{item.userName} · {new Date(item.createdAt).toLocaleString("en-GB", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" })}</Text></View><Text style={[s.adjustQty, item.qty < 0 && s.negative]}>{item.qty >= 0 ? "+" : ""}{item.qty}</Text></View>)}</View> : <Text style={s.empty}>No adjustments recorded yet.</Text>}</View><Modal visible={mode !== null} transparent animationType="slide" onRequestClose={close}><View style={[s.overlay, mobile && s.stockMobileOverlay]}><SafeAreaView style={[s.stockModal, mobile && s.stockMobileModal]}><View style={s.modalHead}><Pressable onPress={close}><Ionicons name="close" size={22} color={colors.muted} /></Pressable><Text style={[s.modalTitle, s.grow]}>{mode === "ADD" ? "Add Stock" : mode === "DEDUCT" ? "Deduct Stock" : "Recount Stock"}</Text></View><ScrollView contentContainerStyle={s.stockModalContent}><Label text={mode === "RECOUNT" ? "HOW MANY IN STOCK?" : "HOW MANY?"} /><View style={s.quantityRow}><Pressable onPress={() => step(-1)} style={s.quantityButton}><Text style={s.quantityButtonText}>−</Text></Pressable><TextInput value={value} onChangeText={setValue} keyboardType="decimal-pad" selectTextOnFocus style={s.quantityInput} /><Pressable onPress={() => step(1)} style={s.quantityButton}><Text style={s.quantityButtonText}>+</Text></Pressable></View><Text style={s.projected}>New stock will be: <Text style={s.projectedStrong}>{projected}</Text> <Text style={s.smallMuted}>(Current Stock: {currentStock})</Text></Text>{mode !== "RECOUNT" && <><Label text="REASON" /><View style={s.reasonChoices}>{(mode ? reasons[mode] : []).map(item => <Pressable key={item} onPress={() => setReason(item)} style={[s.reasonChoice, reason === item && s.reasonChoiceActive]}><Text style={[s.reasonChoiceText, reason === item && s.reasonChoiceActiveText]}>{reasonLabel[item]}</Text></Pressable>)}</View></>}<TextInput value={note} onChangeText={setNote} multiline placeholder="Note (optional)" placeholderTextColor={colors.muted} style={[s.input, s.stockNote]} />{!!error && <Text style={s.error}>{error}</Text>}</ScrollView><View style={s.stockModalFooter}><Pressable disabled={busy} onPress={() => void submit()} style={[s.primary, busy && s.disabled]}>{busy ? <ActivityIndicator color={colors.white} /> : <Text style={s.primaryText}>Save Adjustment</Text>}</Pressable></View></SafeAreaView></View></Modal></View>;
}
function Marketplace({ product, auth, reload }: { product: Product; auth: ReturnType<typeof useAuth>; reload: () => Promise<void> }) {
  type Row = { label: string; value: string; placeholder?: string };
  const sections: { key: MarketplaceSection; title: string }[] = [{ key: "STYLE", title: "Style" }, { key: "FEATURES_SPECS", title: "Features & Specs" }, { key: "ITEM_DETAILS", title: "Item Details" }];
  const initialRows = () => { const grouped: Record<MarketplaceSection, Row[]> = { STYLE: [], FEATURES_SPECS: [], ITEM_DETAILS: [] }; [...(product.marketplaceDetails ?? [])].sort((a, b) => a.sortOrder - b.sortOrder).forEach(item => grouped[item.section].push({ label: item.label, value: item.value })); return grouped; };
  const [youtubeUrl, setYoutubeUrl] = useState(product.youtubeUrl ?? ""); const [marketplacePrice, setMarketplacePrice] = useState(product.marketplacePrice == null ? "" : String(product.marketplacePrice)); const [rows, setRows] = useState<Record<MarketplaceSection, Row[]>>(initialRows); const [templates, setTemplates] = useState<MarketplaceTemplate[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState(""); const [saved, setSaved] = useState(false);
  useEffect(() => { auth.api<MarketplaceTemplate[]>(`/products/marketplace-detail-templates?categoryId=${encodeURIComponent(product.categoryId)}`).then(items => { setTemplates(items); if (!(product.marketplaceDetails ?? []).length) setRows(current => { if (Object.values(current).some(items => items.length)) return current; const next: Record<MarketplaceSection, Row[]> = { STYLE: [], FEATURES_SPECS: [], ITEM_DETAILS: [] }; [...items].sort((a, b) => a.sortOrder - b.sortOrder).forEach(item => next[item.section].push({ label: item.label, value: "", placeholder: item.valuePlaceholder ?? undefined })); return next; }); }).catch(() => setTemplates([])); }, [product.categoryId]);
  const updateRow = (section: MarketplaceSection, index: number, field: "label" | "value", value: string) => setRows(current => ({ ...current, [section]: current[section].map((row, i) => i === index ? { ...row, [field]: value } : row) }));
  const addRow = (section: MarketplaceSection, label = "", placeholder?: string | null) => setRows(current => ({ ...current, [section]: [...current[section], { label, value: "", placeholder: placeholder ?? undefined }] }));
  const removeRow = (section: MarketplaceSection, index: number) => setRows(current => ({ ...current, [section]: current[section].filter((_, i) => i !== index) }));
  const save = async () => { const price = marketplacePrice.trim() ? Number(marketplacePrice) : null; if (price != null && (!Number.isFinite(price) || price < 0)) { setError("Enter a valid marketplace price."); return; } const details: { section: MarketplaceSection; label: string; value: string; sortOrder: number }[] = []; sections.forEach(section => rows[section.key].forEach((row, sortOrder) => { if (row.label.trim() && row.value.trim()) details.push({ section: section.key, label: row.label.trim(), value: row.value.trim(), sortOrder }); })); setBusy(true); setError(""); setSaved(false); try { await auth.api(`/products/${product.id}/marketplace-details`, { method: "PUT", body: JSON.stringify({ youtubeUrl: youtubeUrl.trim() || null, details, marketplacePrice: price }) }); await reload(); setSaved(true); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } };
  return <View style={s.marketplaceSections}><Text style={s.marketplaceIntro}>Optional details shown on the public product page — none of this is required.</Text>{!product.imageUrl && <View style={s.marketWarning}><Text style={s.marketWarningText}>⚠️ Add a product photo before displaying this product in the marketplace.</Text></View>}<View style={s.card}><Label text="MARKETPLACE PRICE (OPTIONAL)" /><TextInput value={marketplacePrice} onChangeText={value => { setMarketplacePrice(value); setSaved(false); }} keyboardType="decimal-pad" placeholder={String(product.sellingPrice)} placeholderTextColor={colors.muted} style={s.input} /><Text style={s.smallMuted}>{marketplacePrice.trim() ? "This price will be shown only on the marketplace." : `Leave blank to show your normal Selling Price on the marketplace too (${money(product.sellingPrice)})`}</Text></View><View><Label text="YOUTUBE VIDEO URL (OPTIONAL)" /><TextInput value={youtubeUrl} onChangeText={value => { setYoutubeUrl(value); setSaved(false); }} autoCapitalize="none" keyboardType="url" placeholder="https://www.youtube.com/watch?v=…" placeholderTextColor={colors.muted} style={s.input} /></View>{sections.map(section => <View key={section.key} style={s.card}><Text style={s.sectionTitle}>{section.title}</Text>{templates.some(item => item.section === section.key) && <><Text style={s.smallMuted}>Pick from template</Text><View style={s.templateChips}>{templates.filter(item => item.section === section.key).map(template => { const added = rows[section.key].some(row => row.label === template.label); return <Pressable key={template.label} disabled={added} onPress={() => addRow(section.key, template.label, template.valuePlaceholder)} style={[s.templateChip, added && s.templateChipAdded]}><Text style={[s.templateChipText, added && s.templateChipAddedText]}>{added ? "✓ " : "+ "}{template.label}</Text></Pressable>; })}</View></>}{rows[section.key].map((row, index) => <View key={index} style={s.marketRow}><TextInput value={row.label} onChangeText={value => updateRow(section.key, index, "label", value)} placeholder="Label" placeholderTextColor={colors.muted} style={[s.input, s.grow]} /><TextInput value={row.value} onChangeText={value => updateRow(section.key, index, "value", value)} placeholder={row.placeholder || "Value"} placeholderTextColor={colors.muted} style={[s.input, s.grow]} /><Pressable accessibilityLabel="Remove row" onPress={() => removeRow(section.key, index)} hitSlop={7}><Ionicons name="close" size={20} color={colors.muted} /></Pressable></View>)}<Pressable onPress={() => addRow(section.key)} style={s.addMarketRow}><Ionicons name="add" size={16} color={colors.primaryDark} /><Text style={s.actionText}>Add row</Text></Pressable></View>)}{!!error && <Text style={s.errorBox}>{error}</Text>}{saved && <Text style={s.savedMessage}>Marketplace details saved.</Text>}<Pressable disabled={busy} onPress={() => void save()} style={[s.primary, busy && s.disabled]}>{busy ? <ActivityIndicator color={colors.white} /> : <Text style={s.primaryText}>Save Marketplace Details</Text>}</Pressable></View>;
}

function EditModal({ visible, product, saving, close, save }: { visible: boolean; product: Product; saving: boolean; close: () => void; save: (payload: object) => Promise<void> }) {
  const [name, setName] = useState(product.name); const [selling, setSelling] = useState(String(product.sellingPrice)); const [market, setMarket] = useState(product.marketPrice == null ? "" : String(product.marketPrice)); const [threshold, setThreshold] = useState(String(product.lowStockThreshold)); const [description, setDescription] = useState(product.description ?? "");
  useEffect(() => { if (visible) { setName(product.name); setSelling(String(product.sellingPrice)); setMarket(product.marketPrice == null ? "" : String(product.marketPrice)); setThreshold(String(product.lowStockThreshold)); setDescription(product.description ?? ""); } }, [visible, product]);
  const submit = () => save({ categoryId: product.categoryId, name: name.trim(), imageUrl: product.imageUrl, description: description.trim() || null, defectNotes: product.defectNotes, unitCode: product.unitCode, sellingPrice: Number(selling), marketPrice: market ? Number(market) : null, packagingCostPerUnit: product.packagingCostPerUnit ?? 0, lowStockThreshold: Number(threshold) || 0, attributesJson: product.attributesJson, note: product.note, status: product.status, rowVer: product.rowVer, warrantyDurationValue: product.warrantyDurationValue, warrantyDurationUnit: product.warrantyDurationUnit, wholesaleMinQty: product.wholesaleMinQty, wholesaleUnitPrice: product.wholesaleUnitPrice, wholesaleNote: product.wholesaleNote });
  return <Modal visible={visible} transparent animationType="fade" onRequestClose={close}><View style={s.overlay}><SafeAreaView style={s.modal}><View style={s.modalHead}><Text style={s.modalTitle}>Edit product</Text><Pressable onPress={close}><Ionicons name="close" size={24} color={colors.heading} /></Pressable></View><ScrollView contentContainerStyle={s.modalContent}><Label text="Product name" /><TextInput value={name} onChangeText={setName} style={s.input} /><Label text="Selling price" /><TextInput value={selling} onChangeText={setSelling} keyboardType="decimal-pad" style={s.input} /><Label text="Market price" /><TextInput value={market} onChangeText={setMarket} keyboardType="decimal-pad" style={s.input} /><Label text="Low stock threshold" /><TextInput value={threshold} onChangeText={setThreshold} keyboardType="number-pad" style={s.input} /><Label text="Description" /><TextInput value={description} onChangeText={setDescription} multiline style={[s.input, s.textarea]} /><Pressable disabled={saving || !name.trim() || Number(selling) <= 0} onPress={() => void submit()} style={[s.primary, saving && s.disabled]}>{saving ? <ActivityIndicator color={colors.white} /> : <Text style={s.primaryText}>Save changes</Text>}</Pressable></ScrollView></SafeAreaView></View></Modal>;
}
function Label({ text }: { text: string }) { return <Text style={s.detailLabel}>{text}</Text>; }

